import {validateMessage} from './validation.js';

it('accepts session list windows, strips userId, and rejects malformed paging fields', () => {
  const before = {sessionId: 'session-1', updatedAt: '2026-01-01T00:00:00.000Z'};
  for (const window of [{}, {limit: 0}, {limit: 200}, {before}, {before: {...before, updatedAt: 0}}]) {
    expect(validateMessage({type: 'list_sessions', ...window, userId: 'another-user'})).toEqual({
      valid: true,
      data: {type: 'list_sessions', ...window},
    });
  }
  for (const limit of [-1, 1.5, '10', null, NaN, Infinity]) {
    expect(validateMessage({type: 'list_sessions', limit})).toEqual({
      valid: false,
      error: expect.stringContaining('limit'),
    });
  }
  for (const cursor of [
    null,
    '2026-01-01',
    {},
    {...before, sessionId: ''},
    {...before, sessionId: 'a'.repeat(129)},
    {...before, sessionId: 1},
    {...before, updatedAt: 'not a date'},
    {...before, updatedAt: null},
    {...before, updatedAt: Infinity},
    {...before, updatedAt: 1e20},
  ]) {
    expect(validateMessage({type: 'list_sessions', before: cursor})).toEqual({
      valid: false,
      error: expect.stringContaining('before'),
    });
  }
});
EOF
